ALL_SCHEDULE.push(...CRYPTO_SCHEDULE.map(row=>[...row,90,'vanya']));
async function seedSchedule(){const ids=ALL_SCHEDULE.map(x=>x[0]),{data,error}=await client.from('planner_events').select('id').in('id',ids);if(error)throw error;const existing=new Set(data.map(x=>x.id)),missing=ALL_SCHEDULE.filter(x=>!existing.has(x[0])).map(([id,startsAt,title,notes,durationMinutes=80,createdBy='ksusha'])=>toRow({id,title,notes,startsAt:new Date(startsAt).toISOString(),durationMinutes,space:'shared',createdBy,done:false,deleted:false,version:0}));if(missing.length){const{error:insertError}=await client.from('planner_events').upsert(missing,{onConflict:'id',ignoreDuplicates:true});if(insertError)throw insertError;await sync()}}
function scheduleMidnightRefresh(){const next=new Date();next.setHours(24,0,1,0);setTimeout(()=>{state.date=new Date();render();cacheWeeks().catch(()=>{});scheduleMidnightRefresh()},next-Date.now())}
async function start(){if(!state.user)return;state.hidePersonal=localStorage.getItem(`hide-personal-${state.user}`)==='1';document.body.dataset.user=state.user;document.querySelector('meta[name="theme-color"]').content=state.user==='vanya'?'#63b795':'#f486a8';$('#chooser').hidden=true;$('#app').hidden=false;setupPullToRefresh();renderProfilePhoto();collaboration.refresh().catch(()=>{});refreshCalendarStatus().catch(()=>{});state.events=await all('events');render();await sync();await seedSchedule().catch(error=>{$('#offline').hidden=false;$('#offline').textContent='Не удалось загрузить расписание · '+error.message});await migrateLoadedEvents().catch(error=>{$('#offline').hidden=false;$('#offline').textContent='Не удалось перенести старые события · '+error.message});if('Notification'in window&&Notification.permission==='granted')ensureNotifications().catch(()=>localStorage.removeItem(`push-registered-${state.user}`));state.events.filter(e=>!e.deleted&&isDeadline(e)&&e.createdBy===state.user&&new Date(e.startsAt)>new Date()).forEach(e=>queueDeadline(e,false).catch(()=>{}));client.channel('planner-live').on('postgres_changes',{event:'*',schema:'public',table:'planner_events'},sync).subscribe();window.addEventListener('online',sync);window.addEventListener('pageshow',()=>sync());document.addEventListener('visibilitychange',()=>{if(!document.hidden)sync()});navigator.storage?.persist?.().catch(()=>{});scheduleMidnightRefresh()}
async function boot(){const cached=localStorage.getItem('planner-last-profile');try{const {data}=await authTimeout(client.auth.getSession(),4500),email=data.session?.user?.email||'';state.user=email.startsWith('vanya@')?'vanya':email.startsWith('ksusha@')?'ksusha':'';if(state.user)localStorage.setItem('planner-last-profile',state.user)}catch{state.user=cached==='vanya'||cached==='ksusha'?cached:''}if(state.user){start();startChatSync()}}
async function applyParticipationSnapshots(rows){const pending=new Set((await all('outbox')).map(row=>row.id)),stored=new Map((await all('events')).map(row=>[row.id,row])),updates=rows.filter(row=>stored.has(row.id)&&!pending.has(row.id)&&Number(row.version)>Number(stored.get(row.id).version));if(!updates.length)return;await put('events',updates);const byId=new Map(updates.map(row=>[row.id,row]));state.events=state.events.map(row=>byId.get(row.id)||row);if(!state.invites)render();}
const collaboration=installCollaboration({state,client,url:CALENDAR_SYNC_URL,render:()=>render(),openEditor,closeEditor,sync,flush,all,applySnapshots:applyParticipationSnapshots});
const renderCalendar=render;
render=()=>{if(state.invites)collaboration.render();else{$('#dateTitle').disabled=false;renderCalendar();}collaboration.badge();};
const eventEditor=installEventEditor({state,saveSeries,closeEditor,ensureNotifications,linkedCopies});
state.chat=new URLSearchParams(location.search).get('view')==='chat';if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js');setInterval(updateCurrentTimeLine,30000);boot();
setInterval(()=>{if(state.user&&!document.hidden)refreshCalendarStatus().catch(()=>{})},120000);
